/// @dev FIXED: checks-effects-interactions plus a transient lock.
contract SafeVault {
    mapping(address => uint256) public balances;
    // keccak256("safe.vault.lock") - 1; inline assembly accepts only
    // direct number constants, never a computed expression.
    uint256 private constant _LOCK =
        0x03b5dbf1876fce72ee2dafac0450e70151c41eeea62e94e53fb27262161e35d5;

    modifier nonReentrant() {
        assembly {
            if tload(_LOCK) { revert(0, 0) }
            tstore(_LOCK, 1)
        }
        _;
        assembly { tstore(_LOCK, 0) }
    }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw() external nonReentrant {
        uint256 amount = balances[msg.sender];
        require(amount > 0, "nothing to withdraw");

        balances[msg.sender] = 0;

        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }
}

