/// @dev VULNERABLE: read-only reentrancy. getPricePerShare() is observable
/// while totalSupply has been reduced but assets have not yet left.
contract SharePriceOracle {
    IVault public vault;

    function getPricePerShare() external view returns (uint256) {
        uint256 supply = vault.totalSupply();
        if (supply == 0) return 1e18;
        return (address(vault).balance * 1e18) / supply;
    }
}

contract LendingMarket {
    SharePriceOracle public oracle;

    function collateralValue(address user, uint256 shares)
        external
        view
        returns (uint256)
    {
        // Reads a price that a redeem() callback can distort mid-transaction.
        return (shares * oracle.getPricePerShare()) / 1e18;
    }
}

