interface AggregatorV3Interface {
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
    function decimals() external view returns (uint8);
}

/// @dev FIXED: validate every field of the Chainlink round.
contract CheckedPriceFeed {
    AggregatorV3Interface public feed;
    uint256 public heartbeat;

    error StalePrice(uint256 updatedAt);
    error InvalidPrice(int256 answer);

    function price() external view returns (uint256) {
        (uint80 roundId, int256 answer, , uint256 updatedAt, uint80 answeredInRound) =
            feed.latestRoundData();

        if (answer <= 0) revert InvalidPrice(answer);
        if (updatedAt == 0 || block.timestamp - updatedAt > heartbeat) revert StalePrice(updatedAt);
        if (answeredInRound < roundId) revert StalePrice(updatedAt);

        return uint256(answer) * (10 ** (18 - feed.decimals()));
    }
}

