pragma solidity ^0.8.20;

/// @dev FIXED: EIP-712 typed data, per-signer nonce, low-s enforcement and a
/// domain separator recomputed if the chain forks.
contract StrongSigAuth {
    bytes32 private constant _TYPEHASH =
        keccak256("Claim(address to,uint256 amount,uint256 nonce,uint256 deadline)");
    bytes32 private immutable _CACHED_SEPARATOR;
    uint256 private immutable _CACHED_CHAIN_ID;
    address public signer;
    mapping(address => uint256) public nonces;

    error ExpiredSignature();
    error InvalidSignature();

    constructor() {
        _CACHED_CHAIN_ID = block.chainid;
        _CACHED_SEPARATOR = _buildSeparator();
    }

    function _buildSeparator() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256("StrongSigAuth"), keccak256("1"), block.chainid, address(this)
        ));
    }

    function domainSeparator() public view returns (bytes32) {
        return block.chainid == _CACHED_CHAIN_ID ? _CACHED_SEPARATOR : _buildSeparator();
    }

    function claim(uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        if (block.timestamp > deadline) revert ExpiredSignature();
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0)
            revert InvalidSignature();

        bytes32 structHash = keccak256(
            abi.encode(_TYPEHASH, msg.sender, amount, nonces[msg.sender]++, deadline)
        );
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator(), structHash));

        address recovered = ecrecover(digest, v, r, s);
        if (recovered == address(0) || recovered != signer) revert InvalidSignature();
    }
}

