/// @dev VULNERABLE: precision loss and wrong rounding direction. Shares round
/// down on mint and on burn, so repeated round-trips leak value to the user.
contract RoundingBug {
    uint256 public totalShares;
    uint256 public totalAssets;

    function toShares(uint256 assets) public view returns (uint256) {
        return (assets * totalShares) / totalAssets;          // floor
    }

    function toAssets(uint256 shares) public view returns (uint256) {
        return (shares * totalAssets) / totalShares;          // floor
    }
}

/// @dev FIXED: always round against the user — down when minting shares,
/// up when charging assets for a redemption.
contract CorrectRounding {
    uint256 public totalShares;
    uint256 public totalAssets;

    function toSharesDown(uint256 assets) public view returns (uint256) {
        return (assets * totalShares) / totalAssets;
    }

    function toAssetsUp(uint256 shares) public view returns (uint256) {
        uint256 product = shares * totalAssets;
        return product == 0 ? 0 : ((product - 1) / totalShares) + 1;
    }
}

