/// @dev Manual calldata decoding with full bounds checking — the pattern an
/// auditor wants to see when a contract parses calldata itself.
contract CalldataDecoder {
    error BadCalldata();

    /// Layout: [4 selector][32 offset][32 length][length * 32 elements]
    function sumArray() external pure returns (uint256 total) {
        assembly {
            if lt(calldatasize(), 0x44) {
                mstore(0x00, 0x1a2e1594)      // BadCalldata()
                revert(0x1c, 0x04)
            }

            let offset := calldataload(0x04)
            // offset must be in range and word-aligned
            if or(gt(offset, 0xffffffff), mod(offset, 0x20)) {
                mstore(0x00, 0x1a2e1594)
                revert(0x1c, 0x04)
            }

            let lenPos := add(0x04, offset)
            if gt(add(lenPos, 0x20), calldatasize()) {
                mstore(0x00, 0x1a2e1594)
                revert(0x1c, 0x04)
            }

            let len := calldataload(lenPos)
            // len * 32 must not overflow and must fit the remaining calldata
            if gt(len, 0xffffffff) {
                mstore(0x00, 0x1a2e1594)
                revert(0x1c, 0x04)
            }
            let dataEnd := add(add(lenPos, 0x20), mul(len, 0x20))
            if gt(dataEnd, calldatasize()) {
                mstore(0x00, 0x1a2e1594)
                revert(0x1c, 0x04)
