import {Test} from "forge-std/Test.sol";

/// @dev Audit harness: a fork test that reproduces a price-manipulation
/// finding, and an invariant that should hold for any vault.
contract PriceManipulationTest is Test {
    IVault vault;
    IPair pair;

    function setUp() public {
        vm.createSelectFork(vm.envString("RPC_URL"), 18_000_000);
        vault = IVault(0x0000000000000000000000000000000000000001);
        pair = IPair(0x0000000000000000000000000000000000000002);
    }

    function test_SpotPriceIsManipulable() public {
        uint256 before = vault.pricePerShare();

        // Move the pool, read the dependent price, restore.
        deal(address(this), 10_000 ether);
        pair.swap(0, 5_000 ether, address(this), "");
        uint256 during = vault.pricePerShare();

        assertGt(during, (before * 150) / 100, "price should not move this far");
    }

    function invariant_SharesNeverExceedAssets() public view {
        assertLe(vault.totalSupply(), vault.totalAssets());
    }
}

interface IVault {
    function pricePerShare() external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function totalAssets() external view returns (uint256);
}

interface IPair {
    function swap(uint256, uint256, address, bytes calldata) external;
